body:
Apache Iceberg version
1.4.2
Query engine
Flink
Please describe the bug 🐞
I am using AWS manage Flink service to read data from Iceberg + Glue tables for real-time streaming joins. However, I have encountered an issue when monitoring the real-time ingestion of new data, particularly with tables that have unique key constraints, causing difficulties in reading the data properly.
flink version: 1.18 and 1.16
iceberg version: 1.4.2
table ：
CREATE CATALOG pro_catalog WITH (
   'type'='iceberg',
   'warehouse'='s3://xxxx-data/iceberg-data/',
   'catalog-impl'='org.apache.iceberg.aws.glue.GlueCatalog',
   'io-impl'='org.apache.iceberg.aws.s3.S3FileIO'
  );

 CREATE TABLE `pro_catalog`.`dim`.`dim_xxx_st` (
  `col_1` VARCHAR NOT NULL,
  `col_2` BIGINT NOT NULL,
  `col_3` TIMESTAMP(6),
  `col_4` DECIMAL(38, 15),
  `col_5` VARCHAR NOT NULL,
  PRIMARY KEY (`col_1`, `col_5`, `col_2`) NOT ENFORCED
) PARTITIONED BY (`col_5`)
WITH (
  'write.parquet.row-group-size-bytes' = '33554432',
  'write.format.default' = 'parquet',
  'write.parquet.compression-codec' = 'zstd',
  'write.target-file-size-bytes' = '67108864',
  'write.distribution-mode' = 'hash',
  'read.split.target-size' = '33554432'
)
java code
    public static void main(String[] args) throws Exception {

        final StreamExecutionEnvironment env2 = StreamExecutionEnvironment.getExecutionEnvironment();
        env2.setParallelism(40);
        env2.setMaxParallelism(40);
        final StreamTableEnvironment tenv = StreamTableEnvironment.create(env2);

        tenv.getConfig().getConfiguration().setString("execution.type", "streaming");

        String database = "sink";
        String catalogName = "pro_catalog";
        String warehousePath = "s3://xxxxx/";
        String catalogImpl = "org.apache.iceberg.aws.glue.GlueCatalog";
        String ioImpl = "org.apache.iceberg.aws.s3.S3FileIO";

        // Load GlueCatalog
        Configuration hadoopConf = new Configuration(false);
        Map<String, String> catalogProperties = new HashMap<>();
        catalogProperties.put("warehouse", warehousePath);
        catalogProperties.put("catalog-impl", catalogImpl);
        catalogProperties.put("io-impl", ioImpl);

        CatalogLoader catalogLoader = CatalogLoader.custom(catalogName, catalogProperties, hadoopConf, catalogImpl);
        Catalog flinkCatalog = new FlinkCatalog(catalogName, database, Namespace.empty(), catalogLoader, true, -1);

        tenv.registerCatalog(catalogName, flinkCatalog);
        tenv.useCatalog(catalogName);

        String priceSql = "select * from pro_catalog.dim.dim_xxxxx   /*+ OPTIONS('streaming'='true', 'monitor-interval'='60s')*/" ;
        Table sourceTable = tenv.sqlQuery(priceSql);
        DataStream<Row> resultStream = tenv.toAppendStream(sourceTable, Row.class);

        resultStream.print();

        env2.execute("Print Flink SQL query result");
    }
I can't read realtime data with incremental file.
log like this:
